import { cn } from '@/shared/ui/utils'

/** Ключи иконок категорий расходов (имена из lucide-react). */
export type DashboardSpendCategoryIcon =
  | 'utensils'
  | 'coffee'
  | 'cross'
  | 'shopping'
  | 'more'
  | 'gamepad'
  | 'storefront'
  | 'bus'
  | 'car-taxi-front'
  | 'cable'
  | 'shirt'
  | 'credit-card'

export type SvgIconProps = Omit<SVGProps<SVGSVGElement>, 'children'>

const lucideCategoryIcons = {
  utensils: Utensils,
  coffee: Coffee,
  cross: Cross,
  shopping: ShoppingBag,
  more: CircleEllipsis,
  gamepad: Gamepad2,
  storefront: Store,
  bus: Bus,
  'car-taxi-front': CarTaxiFront,
  cable: Cable,
  shirt: Shirt,
  'credit-card': CreditCard,
} satisfies Record<DashboardSpendCategoryIcon, LucideIcon>

export function DashboardSpendCategoryIcon({
  name,
  className,
  ...rest
}: {
  name: DashboardSpendCategoryIcon
  className?: string
} & Omit<LucideProps, 'ref'>) {
  const Icon = lucideCategoryIcons[name]

  return <Icon className={cn('size-5 shrink-0', className)} strokeWidth={2} aria-hidden {...rest} />
}

